  function requestSaleAction(saleId: string, type: "voided" | "refunded") { const sale = state.sales.find(s => s.id === saleId); if (!sale || sale.status && sale.status !== "completed") return Alert.alert("Action unavailable", "This sale has already been updated."); setAuthPin("");     setAuthAction({ kind: "sale", saleId, type }); }
  function applySaleAction() { if (!authAction || authAction.kind !== "sale") return; const ownerRecord = state.cashiers.find(c => c.role === "owner" && c.pin === authPin); const validOwner = authPin === state.settings.ownerPin || Boolean(ownerRecord); if (!validOwner) return Alert.alert("Owner authorization required", "Only the owner PIN or app PIN can approve refunds and voids."); const target = state.sales.find(s => s.id === authAction.saleId); if (!target) return; const actionAt = new Date().toISOString(); const auditType: "refund" | "void" = authAction.type === "voided" ? "void" : "refund"; setState(s => ({ ...s, sales: s.sales.map(sale => sale.id === target.id ? { ...sale, status: authAction.type, refund: authAction.type === "refunded" ? sale.total : sale.refund, authorizedBy: ownerRecord?.name || "Owner", actionAt } : sale), products: s.products.map(product => { const line = target.items.find(item => item.productId === product.id); return line ? { ...product, soldStock: Math.max(0, product.soldStock - line.quantity) } : product; }), stockAdjustments: [...target.items.map(item => ({ id: freshId("adjust"), productId: item.productId, quantity: item.quantity, type: auditType, note: `${auditType.toUpperCase()} ${target.id}`, createdAt: actionAt, createdBy: activeShift?.cashierName || "Owner" })), ...s.stockAdjustments], auditLog: [{ id: freshId("audit"), type: auditType, action: `${auditType.toUpperCase()} sale ${target.id}`, cashierName: activeShift?.cashierName, saleId: target.id, authorizedBy: ownerRecord?.name || "Owner", createdAt: actionAt }, ...s.auditLog] })); setAuthAction(undefined); setAuthPin(""); Alert.alert(authAction.type === "voided" ? "Sale voided" : "Sale refunded", "The stock balance and audit record were updated locally."); }
