  function applyStockAdjustment(productId: string, quantity: number, authorizedBy: string) { const product = state.products.find(p => p.id === productId); if (!product) return; const actionAt = new Date().toISOString(); setState(s => ({ ...s, products: s.products.map(p => p.id === productId ? { ...p, overallStock: p.overallStock + quantity, updatedAt: actionAt } : p), stockAdjustments: [{ id: freshId("adjust"), productId, quantity, type: "restock", createdAt: actionAt, createdBy: activeShift?.cashierName || "Owner", note: "Manual restock" }, ...s.stockAdjustments], auditLog: [{ id: freshId("audit"), type: "stock", action: `RESTOCK ${product.name}`, cashierName: activeShift?.cashierName || "Owner", productId, quantity, authorizedBy, createdAt: actionAt }, ...s.auditLog] })); setAuthAction(undefined); setAuthPin(""); Alert.alert("Stock updated", `${product.name} restocked by ${quantity}.`); }
  function applyMpesaReconciliationAuthorization() { const action = authAction; if (!action || action.kind !== "mpesa-reconcile") return; const ownerRecord = state.cashiers.find(c => c.role === "owner" && c.pin === authPin); const reconciler = ownerRecord?.name || activeShift?.cashierName || "Owner"; const authorized = canAuthorizeSensitiveAction({ action: "mpesa-reconcile", inputPin: authPin, appPin: state.settings.ownerPin, editPin: state.settings.editPin, cashierEditPin: state.cashiers.find(c => c.name === activeShift?.cashierName)?.editPin, ownerPin: state.settings.ownerPin, ownerCashierPin: ownerRecord?.pin, editPinEnabled: true }); if (!authorized) return Alert.alert("Edit PIN required", "Enter the configured edit PIN or an owner PIN before reconciling M-Pesa payments."); const actionAt = new Date().toISOString(); const ids = new Set(action.saleIds); const targets = state.sales.filter(sale => ids.has(sale.id) && sale.paymentMethod === "mpesa_manual" && sale.reconciliationStatus !== "reconciled"); if (!targets.length) return Alert.alert("Nothing to reconcile", "All selected M-Pesa payments are already reconciled or unavailable."); setState(s => ({ ...s, sales: s.sales.map(sale => ids.has(sale.id) ? reconcileMpesaSale(sale, reconciler, actionAt) : sale), auditLog: [...targets.map(sale => ({ id: freshId("audit"), type: "reconciliation" as const, action: "RECONCILE M-PESA " + (sale.mpesaReceiptNumber || sale.id), cashierName: activeShift?.cashierName || "Owner", saleId: sale.id, authorizedBy: reconciler, createdAt: actionAt })), ...s.auditLog] })); setSelectedMpesaIds([]); setAuthAction(undefined); setAuthPin(""); Alert.alert("M-Pesa reconciled", targets.length + " local payment record" + (targets.length === 1 ? " is" : "s are") + " marked reconciled."); }
  function requestMpesaReconciliation(saleIds: string[]) { const ids = [...new Set(saleIds)].filter(id => state.sales.some(sale => sale.id === id && sale.paymentMethod === "mpesa_manual" && sale.reconciliationStatus !== "reconciled")); if (!ids.length) return Alert.alert("No unreconciled payments", "Select at least one unreconciled manual M-Pesa transaction."); setAuthPin(""); setAuthAction({ kind: "mpesa-reconcile", saleIds: ids }); }
