  function applySensitiveAuthorization() { if (!authAction) return; if (authAction.kind === "sale") return applySaleAction(); if (authAction.kind === "mpesa-reconcile") return applyMpesaReconciliationAuthorization(); if (authAction.kind === "stock") { const ownerRecord = state.cashiers.find(c => c.role === "owner" && c.pin === authPin); const authorized = canAuthorizeSensitiveAction({ action: "stock-adjust", inputPin: authPin, appPin: state.settings.ownerPin, editPin: state.settings.editPin, cashierEditPin: state.cashiers.find(c => c.name === activeShift?.cashierName)?.editPin, ownerPin: state.settings.ownerPin, ownerCashierPin: ownerRecord?.pin, editPinEnabled: state.settings.editPinEnabled }); if (!authorized) return Alert.alert("Authorization required", "Enter the configured edit PIN or an owner PIN to adjust stock."); return applyStockAdjustment(authAction.productId, authAction.quantity, ownerRecord?.name || activeShift?.cashierName || "Owner"); } const ownerRecord = state.cashiers.find(c => c.role === "owner" && c.pin === authPin); const authorized = canAuthorizeSensitiveAction({ action: "sale-delete", inputPin: authPin, appPin: state.settings.ownerPin, ownerPin: state.settings.ownerPin, ownerCashierPin: ownerRecord?.pin, editPinEnabled: true }); if (!authorized) return Alert.alert("Owner authorization required", "Only the owner PIN can delete a sale."); const actionAt = new Date().toISOString(); setState(s => ({ ...s, sales: s.sales.filter(sale => sale.id !== authAction.saleId), auditLog: [{ id: freshId("audit"), type: "void", action: `DELETE sale ${authAction.saleId}`, cashierName: activeShift?.cashierName, authorizedBy: ownerRecord?.name || "Owner", saleId: authAction.saleId, createdAt: actionAt }, ...s.auditLog] })); setAuthAction(undefined); setAuthPin(""); Alert.alert("Sale deleted", "The sale and its audit record were removed locally."); }
