  function addToCart(product: Product) { setCart(lines => { const found = lines.find(l => l.productId === product.id); return found ? lines.map(l => l.productId === product.id ? { ...l, quantity: l.quantity + 1 } : l) : [...lines, { productId: product.id, quantity: 1, unitPrice: product.price }]; }); }
