  function endShift() { if (!activeShift || !activeShiftSummary) return; Alert.alert("End this shift?", `${activeShiftSummary.shiftName} • ${activeShift.cashierName}\n${activeShiftSummary.transactions} sale(s) • ${money(activeShiftSummary.netSales, state.settings.currency)} net sales`, [{ text: "Keep shift open", style: "cancel" }, { text: "End shift", style: "destructive", onPress: () => { const endedAt = new Date().toISOString(); setState(s => ({ ...s, shifts: s.shifts.map(sh => sh.id === activeShift.id ? { ...sh, endedAt } : sh), activeShiftId: undefined })); setPosTab("cashier"); setContactToast("Shift ended and summary saved locally"); setTimeout(() => setContactToast(""), 2200); } }]); }
  function clearCart() { if (!cart.length) return; Alert.alert("Clear cart?", "This removes the current sale from checkout.", [{ text: "Keep cart", style: "cancel" }, { text: "Clear", style: "destructive", onPress: () => { setCart([]); setAmountGiven(""); setDiscount(""); setPaymentMethod("cash"); setMpesaReceiptNumber(""); setMpesaPhone(""); } }]); }
