  function completeSale() { if (!activeShift) return Alert.alert("Start a shift first", "Open POS and enter a cashier name to start recording sales."); if (!cartLines.length) return; if (given < total) return Alert.alert("Payment incomplete", "Record the full amount before completing this sale."); if (paymentMethod === "mpesa_manual" && !mpesaReceiptNumber.trim()) return Alert.alert("M-Pesa receipt required", "Enter the customer’s M-Pesa confirmation code. No live request is sent."); if (paymentMethod === "mpesa_manual" && hasDuplicateMpesaReceipt(state.sales, mpesaReceiptNumber)) return Alert.alert("Duplicate M-Pesa code", "That confirmation code is already recorded on another sale."); const sale: Sale = { id: freshId("sale"), shiftId: activeShift.id, cashierName: activeShift.cashierName, createdAt: new Date().toISOString(), items: cartLines.map(x => ({ productId: x.product.id, name: x.product.name, quantity: x.quantity, quantityType: x.product.quantityType, unitPrice: x.unitPrice, lineTotal: x.quantity * x.unitPrice })), subtotal, discount: Number(discount || 0), refund: 0, total, amountGiven: given, change, paymentMethod, mpesaReceiptNumber: paymentMethod === "mpesa_manual" ? mpesaReceiptNumber.trim() : undefined, mpesaPhone: paymentMethod === "mpesa_manual" ? mpesaPhone.trim() || undefined : undefined, reconciliationStatus: paymentMethod === "mpesa_manual" ? "unreconciled" : undefined }; setState(s => ({ ...s, sales: [sale, ...s.sales], products: s.products.map(p => { const line = cartLines.find(x => x.product.id === p.id); return line ? { ...p, soldStock: p.soldStock + line.quantity } : p; }) })); setCart([]); setAmountGiven(""); setDiscount(""); setPaymentMethod("cash"); setMpesaReceiptNumber(""); setMpesaPhone(""); Alert.alert("Sale saved", paymentMethod === "mpesa_manual" ? "Manual M-Pesa record saved locally as unreconciled." : "Transaction stored on this device."); setPosTab("sell"); }
