  function calculate(value: string) { try { const safe = value.replace(/[^0-9+\-*/().%]/g, ""); const normalized = safe.replace(/(\d+(?:\.\d+)?)%/g, "($1/100)"); const result = Function(`"use strict"; return (${normalized || 0})`)(); return Number.isFinite(result) ? String(result) : "0"; } catch { return "0"; } }
  function pressCalc(key: string) { if (key === "C") return setCalc("0"); if (key === "⌫") return setCalc(v => v.length > 1 ? v.slice(0, -1) : "0"); if (key === "=") { const result = calculate(calc); setState(s => ({ ...s, calculatorHistory: [`${calc} = ${result}`, ...s.calculatorHistory].slice(0, 30) })); return setCalc(result); } if (key === "M+") return setCalcMemory(calcMemory + Number(calculate(calc))); if (key === "M-") return setCalcMemory(calcMemory - Number(calculate(calc))); if (key === "MC") return setCalcMemory(0); if (key === "MR") return setCalc(String(calcMemory)); if (["sin", "cos", "tan", "sqrt", "log"].includes(key)) { const n = Number(calculate(calc)); const result = key === "sin" ? Math.sin(n) : key === "cos" ? Math.cos(n) : key === "tan" ? Math.tan(n) : key === "sqrt" ? Math.sqrt(n) : Math.log10(n); setCalc(String(Number(result.toFixed(8)))); return; } setCalc(v => v === "0" && /\d/.test(key) ? key : v + key); }
  function balancePosCalcExpression(value: string) { const safe = value.replace(/[^0-9+\-*/().%]/g, ""); const open = (safe.match(/\(/g) || []).length; const close = (safe.match(/\)/g) || []).length; return close < open ? `${safe}${")".repeat(open - close)}` : safe; }
  function evaluatePosCalc(value: string): number | undefined { const safe = value.replace(/[^0-9+\-*/().%]/g, ""); if (!safe.trim() || /[+\-*/.]$/.test(safe)) return undefined; const normalized = safe.replace(/(\d+(?:\.\d+)?)%/g, "($1/100)"); try { const result = Function(`"use strict"; return (${normalized})`)(); const number = Number(result); return Number.isFinite(number) ? number : undefined; } catch { return undefined; } }
  function getPosCalcIssue(value: string): { kind: "empty" | "incomplete" | "parentheses" | "divide" | "invalid" | "valid"; message: string } { const safe = value.replace(/[^0-9+\-*/().%]/g, ""); if (!safe || safe === "0") return { kind: "empty", message: "Start with a number." }; if (/[+\-*/.]$/.test(safe)) return { kind: "incomplete", message: "Finish the expression after the operator." }; const open = (safe.match(/\(/g) || []).length; const close = (safe.match(/\)/g) || []).length; if (open > close) return { kind: "parentheses", message: state.settings.autoBalanceParentheses ? `Equals will add ${open - close} closing parenthesis${open - close === 1 ? "" : "es"}.` : "Add a closing parenthesis or enable auto-balance." }; if (close > open) return { kind: "parentheses", message: "Remove the extra closing parenthesis." }; if (/\/\s*0(?:\.0*)?(?:\D|$)/.test(safe)) return { kind: "divide", message: "Divide by zero is not allowed." }; return evaluatePosCalc(safe) === undefined ? { kind: "invalid", message: "Check the expression before pressing equals." } : { kind: "valid", message: "Expression looks valid." }; }
