  function pressPosCalc(key: string) { setPosCalcError(""); if (key === "C") { setPosCalc("0"); return; } if (key === "⌫") { setPosCalc(value => value.length > 1 ? value.slice(0, -1) : "0"); return; } if (key === "=") { const expression = state.settings.autoBalanceParentheses ? balancePosCalcExpression(posCalc) : posCalc; const issue = getPosCalcIssue(expression); const result = evaluatePosCalc(expression); if (result === undefined) { setPosCalcError(issue.message); return; } setPosCalc(String(result)); return; } if (key === "M+") return setPosCalcMemory(value => value + Number(calculate(posCalc))); if (key === "M-") return setPosCalcMemory(value => value - Number(calculate(posCalc))); if (key === "MR") return setPosCalc(String(posCalcMemory)); if (key === "MC") return setPosCalcMemory(0); setPosCalc(value => normalizePosCalcInput(value === "0" && /\d/.test(key) ? key : value + key)); }
