  function compareVersions(local: string, known: string) { const parse = (value: string) => value.replace(/^v/i, "").split(".").map(part => Number.parseInt(part, 10) || 0); const a = parse(local); const b = parse(known); for (let index = 0; index < Math.max(a.length, b.length); index += 1) { if ((a[index] || 0) !== (b[index] || 0)) return (a[index] || 0) < (b[index] || 0) ? -1 : 1; } return 0; }
