  function reconciliationHtml() { const rows = buildReconciliationExportRows(reconciliationHistory, state.sales, eatDateKey); const period = `${reconciliationFrom || "Earliest"} → ${reconciliationTo || "Today"}`; const cashierLabel = reconciliationCashierFilter === "All" ? "All cashiers" : reconciliationCashierFilter; return `<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width, initial-scale=1"/><style>@page{margin:16mm}body{font-family:Arial,sans-serif;color:#0D1B2A}h1{color:#D76500;margin-bottom:4px}p{color:#516274;font-size:12px}table{width:100%;border-collapse:collapse;margin-top:16px}th{background:#0D1B2A;color:#FFF8EC;text-align:left}th,td{padding:7px 5px;border-bottom:1px solid #D7C7A5;font-size:10px}.amount{text-align:right}</style></head><body><h1>ShopMate Offline</h1><h2>M-Pesa Reconciliation History</h2><p>Period: ${escapeHtml(period)} (EAT) • ${escapeHtml(cashierLabel)} • ${rows.length} record(s)</p><table><thead><tr><th>Reconciled</th><th>Code</th><th>Sale cashier</th><th>Authorized by</th><th class="amount">Amount</th><th>Status</th></tr></thead><tbody>${rows.map(row => `<tr><td>${escapeHtml(formatEAT(row.reconciledAt, "dateTime"))}</td><td>${escapeHtml(row.receiptNumber)}</td><td>${escapeHtml(row.saleCashier || "Archived")}</td><td>${escapeHtml(row.authorizedBy)}</td><td class="amount">${escapeHtml(money(row.amount, state.settings.currency))}</td><td>${row.status.toUpperCase()}</td></tr>`).join("") || `<tr><td colspan="6">No reconciliation records match the selected filters.</td></tr>`}</tbody></table><p>Dev by JM Majiwa • Support: streetpandacyber@gmail.com • WhatsApp: 0745198099</p></body></html>`; }
